def test_update_pet_invalid_auth(api_client):
    """
    Test updating a pet with invalid authentication.
    """
    endpoint = '/pet'
    method = 'PUT'
    request_data = {
        "name": "doggie",
        "photoUrls": ["http://example.com/photo1.jpg"]
    }
    
    headers = {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer invalid_token'
    }
    
    response = api_client.put(endpoint, data=json.dumps(request_data), headers=headers)
    
    assert response.status_code == 401, "Expected status code 401 for invalid authentication"

